struct Component {
    virtual ~Component() = default;
    virtual std::string read() const = 0; };
struct Decorator : Component {                       // conforms to Component
    explicit Decorator(std::unique_ptr<Component> inner) : inner_(std::move(inner)) {}
    std::string read() const override { return inner_->read(); }   // forward once
    std::unique_ptr<Component> inner_;
};
struct Upper : Decorator {
    using Decorator::Decorator;                      // inherit the ctor
    std::string read() const override { return to_upper(Decorator::read()); }
};  // auto c = std::make_unique<Upper>(std::make_unique<File>("/tmp/x"));

template <class Base>
struct Upper : Base {
    using Base::Base;                                  // inherit constructors
    std::string read() const { return to_upper(Base::read()); }
};

// composed at compile time, zero virtual dispatch:
Upper<Counting<FileSource>> src{FileSource{"/tmp/x"}};
static_assert(std::is_base_of_v<FileSource, decltype(src)>);

